//! Texture cache: decodes image files, builds mipmaps and keeps the results under a memory limit, evicting the least
//! recently used texture first. Procedural textures are generated by the caller and stored the same way.

mod bitmap;
mod height;
mod loader;

pub use bitmap::{Bitmap, MipChain, Usage};
pub use height::normal_from_height;
pub use loader::{decode, LoadError};

use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;

/// Default memory limit: 256 MiB of texels.
pub const DEFAULT_BUDGET: usize = 256 * 1024 * 1024;
/// Largest side kept for a loaded image; bigger images lose their top mip levels.
pub const MAX_SIDE: usize = 4096;

struct Entry {
    chain: Arc<MipChain>,
    bytes: usize,
    last_used: u64,
    origin: String,
}

/// Memory-limited cache of mipmapped textures.
pub struct TextureCache {
    budget: usize,
    used: usize,
    tick: u64,
    entries: HashMap<String, Entry>,
    failures: HashMap<String, LoadError>,
}

impl Default for TextureCache {
    fn default() -> Self {
        Self::new(DEFAULT_BUDGET)
    }
}

/// Turns a decoded or generated bitmap into the stored chain for `usage`.
fn finish(bitmap: Bitmap, usage: Usage) -> MipChain {
    let bitmap = match usage {
        Usage::Height => {
            let side = bitmap.width.max(bitmap.height) as f32;
            normal_from_height(&bitmap, (side * 0.04).clamp(1.0, 24.0))
        }
        _ => bitmap,
    };
    let mut chain = MipChain::build(bitmap, usage == Usage::Color);
    chain.limit_size(MAX_SIDE);
    chain
}

impl TextureCache {
    /// An empty cache that holds at most `budget` bytes (one texture larger than that is still kept while in use).
    pub fn new(budget: usize) -> Self {
        Self {
            budget,
            used: 0,
            tick: 0,
            entries: HashMap::new(),
            failures: HashMap::new(),
        }
    }

    /// The texture of the image file at `path`, loading it on first use. Failures are remembered until
    /// [`invalidate`](Self::invalidate) so a missing file is not retried every frame.
    pub fn get_file(&mut self, path: &Path, usage: Usage) -> Result<Arc<MipChain>, LoadError> {
        let origin = path.to_string_lossy().into_owned();
        let key = format!("file:{origin}|{usage:?}");
        if let Some(found) = self.touch(&key) {
            return Ok(found);
        }
        if let Some(error) = self.failures.get(&origin) {
            return Err(*error);
        }
        match loader::load_file(path) {
            Ok(bitmap) => Ok(self.insert(key, origin, finish(bitmap, usage))),
            Err(error) => {
                self.failures.insert(origin, error);
                Err(error)
            }
        }
    }

    /// The texture stored under `key`, generating it with `make` on first use.
    pub fn get_generated(
        &mut self,
        key: &str,
        usage: Usage,
        make: impl FnOnce() -> Bitmap,
    ) -> Arc<MipChain> {
        let key = format!("gen:{key}|{usage:?}");
        if let Some(found) = self.touch(&key) {
            return found;
        }
        let origin = key.clone();
        self.insert(key, origin, finish(make(), usage))
    }

    /// Forgets the file at `path` (every usage) and any remembered failure, so it is read again next time.
    pub fn invalidate(&mut self, path: &Path) {
        let origin = path.to_string_lossy().into_owned();
        self.failures.remove(&origin);
        let stale: Vec<String> = self
            .entries
            .iter()
            .filter(|(_, e)| e.origin == origin)
            .map(|(k, _)| k.clone())
            .collect();
        for key in stale {
            self.remove(&key);
        }
    }

    /// Drops every texture and failure.
    pub fn clear(&mut self) {
        self.entries.clear();
        self.failures.clear();
        self.used = 0;
    }

    /// Changes the memory limit, evicting textures if needed.
    pub fn set_budget(&mut self, budget: usize) {
        self.budget = budget;
        self.evict(None);
    }

    /// Bytes currently held.
    pub fn used_bytes(&self) -> usize {
        self.used
    }

    /// The memory limit in bytes.
    pub fn budget(&self) -> usize {
        self.budget
    }

    /// Number of textures held.
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// Whether no texture is held.
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    fn touch(&mut self, key: &str) -> Option<Arc<MipChain>> {
        self.tick += 1;
        let tick = self.tick;
        let entry = self.entries.get_mut(key)?;
        entry.last_used = tick;
        Some(entry.chain.clone())
    }

    fn insert(&mut self, key: String, origin: String, chain: MipChain) -> Arc<MipChain> {
        self.tick += 1;
        let bytes = chain.bytes();
        let chain = Arc::new(chain);
        self.remove(&key);
        self.entries.insert(
            key.clone(),
            Entry {
                chain: chain.clone(),
                bytes,
                last_used: self.tick,
                origin,
            },
        );
        self.used += bytes;
        self.evict(Some(&key));
        chain
    }

    fn remove(&mut self, key: &str) {
        if let Some(entry) = self.entries.remove(key) {
            self.used -= entry.bytes;
        }
    }

    /// Evicts least recently used textures until under budget, never touching `keep`.
    fn evict(&mut self, keep: Option<&str>) {
        while self.used > self.budget {
            let oldest = self
                .entries
                .iter()
                .filter(|(k, _)| Some(k.as_str()) != keep)
                .min_by_key(|(_, e)| e.last_used)
                .map(|(k, _)| k.clone());
            match oldest {
                Some(key) => self.remove(&key),
                None => break,
            }
        }
    }
}

